class ToyReweight:
    """Custom MC weight with symmetric +/- 5% variations"""
    name = "toy_reweight"
    has_variations = True

    @staticmethod
    def weight(events):
        # Normalize LHEWeight_originalXWGTUP to mean of 1
        nominal = events.LHEWeight_originalXWGTUP / events.LHEWeight_originalXWGTUP.mean()

        return {
            "nominal": nominal,
            "up": nominal * 1.05,
            "down": nominal * 0.95,
        }


# Usage in PocketCoffea configuration:
# config = {
#     "weights_classes": [ToyReweight],
# }

